28	export function DiagramLegendEntryRow({ entry, session, store }: {
29	    entry: DiagramLegendEntry, session?: DiagramEditSessionService, store: DiagramFormattingMutationStore,
30	}) {
31	    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
32	    const [draftState, setDraftState] = useState({ base: entry.label, value: entry.label })
33	    const draftLabel = draftState.base === entry.label ? draftState.value : entry.label
34	    const [labelError, setLabelError] = useState<string | null>(null)
35	    const entryKey = entry.entryType === 'node' ? `node:${entry.role}` : `connection:${entry.kind}`
36	    const handleLabelChange = (event: ChangeEvent<HTMLInputElement>) => {
37	        setDraftState({ base: entry.label, value: event.target.value })
38	        setLabelError(null)
39	    }
40	    const commitLabel = () => {
41	        if (!session || draftLabel.trim() === entry.label) return
42	        if (!draftLabel.trim()) {
43	            setLabelError('Label is required.')
44	
45	            return
46	        }
47	        session.materializeDerivedLegend()
48	        if (!session.setLegendEntryLabel(entryKey, draftLabel)) setLabelError('Label could not be saved.')
49	    }
50	    const handleLabelKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
51	        if (event.key === 'Enter') {
52	            event.preventDefault()
53	            commitLabel()
54	        }
55	        if (event.key === 'Escape') {
56	            setDraftState({ base: entry.label, value: entry.label })
57	            setLabelError(null)
58	        }
59	    }
60	    const handleRemove = () => {
61	        session?.materializeDerivedLegend()
62	        session?.removeLegendEntry(entryKey)
63	    }
64	    const nodeFormatting = useDiagramNodeRoleFormatting(entry.entryType === 'node' ? entry.role : 'focal', store)
65	    const handleOpen = (event: MouseEvent<HTMLButtonElement>) => setAnchorElement(event.currentTarget)
66	    const handleClose = () => setAnchorElement(null)
67	    const handleNodeApply = (value: DiagramNodeRoleFormatting) => {
68	        if (entry.entryType === 'node') store.setNodeRoleFormatting(entry.role, value)
69	    }
70	    const handleConnectionApply = (value: DiagramConnectionKindFormatting) => {
71	        if (entry.entryType === 'connection') store.setConnectionKindFormatting(entry.kind, value)
72	    }
73	
74	    return (
75	        <Box
76	            sx={{
77	                alignItems: 'center', display: 'flex', gap: 1,
78	                '& .diagram-formatting-action': { opacity: 0 },
79	                '&:focus-within .diagram-formatting-action, &:hover .diagram-formatting-action': { opacity: 1 },
80	                '@media (hover: none)': { '& .diagram-formatting-action': { opacity: 1 } },
81	            }}
82	        >
83	            {entry.entryType === 'node' ? (
84	                <Box
85	                    data-role={entry.role}
86	                    sx={{ border: '1px solid', borderRadius: 0.5, flexShrink: 0, height: 12, width: 20, ...diagramRoleStyle(entry.role, nodeFormatting) }}
87	                />
88	            ) : <DiagramLegendConnectionSample kind={entry.kind} store={store} />}
89	            {session ? (
90	                <TextField
91	                    error={!!labelError}
92	                    helperText={labelError}
93	                    onBlur={commitLabel}
94	                    onChange={handleLabelChange}
95	                    onKeyDown={handleLabelKeyDown}
96	                    size="small"
97	                    slotProps={{ htmlInput: { 'aria-label': `Legend label for ${entryKey}` } }}
98	                    sx={{ flex: 1, minWidth: 0 }}
99	                    value={draftLabel}
100	                />
101	            ) : <Typography color="text.secondary" sx={{ flex: 1, minWidth: 0 }} variant="caption">{entry.label}</Typography>}
102	            {session ? (
103	                <Tooltip title={`Remove ${entry.label}`}>
104	                    <IconButton aria-label={`Remove ${entry.label}`} className="diagram-formatting-action" onClick={handleRemove} size="small">
105	                        <DeleteOutlineOutlined fontSize="small" />
106	                    </IconButton>
107	                </Tooltip>
108	            ) : null}
109	            <Tooltip title={`Format ${entry.label}`}>
110	                <IconButton
111	                    aria-label={`Format ${entry.label}`}
112	                    className="diagram-formatting-action"
113	                    onClick={handleOpen}
114	                    size="small"
115	                >
116	                    <SettingsOutlined fontSize="small" />
117	                </IconButton>
118	            </Tooltip>
119	            {anchorElement && entry.entryType === 'node' ? (
120	                <NodeFormattingPopover
121	                    anchorElement={anchorElement}
122	                    label={entry.label}
123	                    onApply={handleNodeApply}
124	                    onClose={handleClose}
125	                    value={store.getNodeRoleFormattingSnapshot(entry.role)}
126	                />
127	            ) : null}
128	            {anchorElement && entry.entryType === 'connection' ? (
129	                <ConnectionFormattingPopover
130	                    anchorElement={anchorElement}
131	                    kind={entry.kind}
132	                    label={entry.label}
133	                    onApply={handleConnectionApply}
134	                    onClose={handleClose}
135	                    value={store.getConnectionKindFormattingSnapshot(entry.kind)}
136	                />
137	            ) : null}
138	        </Box>
139	    )
140	}
